# Lists Python registrations and PATH candidates visible to the student; use a python.exe path in PyCharm settings.
# run-as: user
# timeout: 30
$ErrorActionPreference = 'Stop'
$found = $false
foreach ($root in @('HKCU:\Software\Python', 'HKLM:\Software\Python', 'HKLM:\Software\WOW6432Node\Python')) {
    foreach ($company in @(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue)) {
        foreach ($tag in @(Get-ChildItem -LiteralPath $company.PSPath -ErrorAction SilentlyContinue)) {
            $install = Get-Item -LiteralPath ($tag.PSPath + '\InstallPath') -ErrorAction SilentlyContinue
            if ($install) {
                $path = $install.GetValue('ExecutablePath')
                if (-not $path -and $install.GetValue('')) { $path = Join-Path $install.GetValue('') 'python.exe' }
                if ($path) {
                    $visible = Test-Path -LiteralPath $path -PathType Leaf
                    Write-Output "$($tag.PSChildName): $path (visible to this user: $visible)"
                    $found = $true
                }
            }
        }
    }
}
foreach ($command in @(Get-Command python.exe, python3.exe, py.exe -CommandType Application -ErrorAction SilentlyContinue)) {
    Write-Output "PATH candidate: $($command.Source) (may be a Windows Store alias)"
    $found = $true
}
if (-not $found) { Write-Output 'No Python registration or PATH candidate visible. Check the Python installation for all users.' }
Write-Output 'In PyCharm, select an existing interpreter using its full python.exe path. This script does not execute Python or change settings.'
exit 0

# Opens IntelliJ IDEA with UAC; administrator credentials are required on the PC.
# run-as: user
# timeout: 120
$ErrorActionPreference = 'Stop'
# Set this only for a portable/custom installation not found below.
$overridePath = ''
$executables = @('idea64.exe', 'idea.exe')
$patterns = @('JetBrains\IntelliJ IDEA*\bin\idea64.exe', 'Programs\IntelliJ IDEA*\bin\idea64.exe', 'JetBrains\Toolbox\apps\idea*\bin\idea64.exe', 'JetBrains\Toolbox\apps\IDEA*\*\*\bin\idea64.exe')
$candidates = @()
if ($overridePath) {
    if (-not (Test-Path -LiteralPath $overridePath -PathType Leaf)) { throw "Executable not found: $overridePath" }
    $candidates += $overridePath
} else {
    foreach ($exe in $executables) {
        foreach ($hive in @('HKCU:', 'HKLM:')) {
            foreach ($key in @('SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths', 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths')) {
                $entry = Get-Item -LiteralPath "$hive\$key\$exe" -ErrorAction SilentlyContinue
                if ($entry -and $entry.GetValue('')) { $candidates += $entry.GetValue('').Trim('"') }
            }
        }
        $command = Get-Command $exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($command) { $candidates += $command.Source }
    }
    $roots = @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:LOCALAPPDATA) | Where-Object { $_ } | Select-Object -Unique
    foreach ($root in $roots) {
        foreach ($pattern in $patterns) {
            $candidates += Get-ChildItem -Path (Join-Path $root $pattern) -File -ErrorAction SilentlyContinue |
                Sort-Object LastWriteTime -Descending | Select-Object -ExpandProperty FullName
        }
    }
}
$path = $candidates | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Leaf) } | Select-Object -First 1
if (-not $path) { throw 'IntelliJ IDEA was not found. Install it or set $overridePath to its executable.' }
Write-Output "Approve the UAC prompt on this PC; cancel it to stop. An existing app may reuse its current privileges."
Start-Process -FilePath $path -WorkingDirectory (Split-Path -Parent $path) -Verb RunAs -ErrorAction Stop
Write-Output "Launch requested: $path"
exit 0

